password = "Python2026"
has_letter = False
has_digit = False
has_space = False
for character in password:
    if character.isalpha():
        has_letter = True
    if character.isdecimal():
        has_digit = True
    if character.isspace():
        has_space = True
if len(password) >= 8 and has_letter and has_digit and not has_space:
